"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["90690"],{89489(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>c,contentTitle:()=>p,toc:()=>h,assets:()=>d});var i=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-participant-update","title":"Participant update (v1)","description":"Updates a participant\'s registry record; participant_code and roles are mandatory, every other field (certificate, endpoint, contacts, status) is optional.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-participant-update.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-participant-update","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-participant-update","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Participant update (v1)","sidebar_label":"Participant update (v1)","sidebar_class_name":"api-method api-method--post","description":"Updates a participant\'s registry record; participant_code and roles are mandatory, every other field (certificate, endpoint, contacts, status) is optional.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Get session token","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-get-session"},"next":{"title":"Participant certificate and bridge update (v2)","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-update"}}'),r=a(62540),n=a(43023),s=a(70862),o=JSON.parse('{"id":"registry_participant_update","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/participant/update","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Participant update (v1)","description":"Updates a participant\'s registry record; participant_code and roles are mandatory, every other field (certificate, endpoint, contacts, status) is optional.\\n\\n### Business purpose\\n\\nParticipant details change over the life of an integration: callback endpoints move, encryption certificates are rotated annually, contact numbers and payment details change. The registry is the source of truth that the gateway routes from, so those changes must land there, not just in the participant\'s own configuration. This v1 update lets an organisation amend any attribute of its full record in one synchronous call, and the sandbox onboarding document names it as the way to update the bridge URL, the encryption certificate or any other attribute.\\n\\n### When to use\\n\\nUse it after registration whenever a registry attribute must change. The FAQ lists the sandbox Update Participant URL as https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/update, while production onboarding documents the narrower /v2/participant/update plus /update/validate for certificate and bridge changes. It is a plain JSON registry call outside the JWE protocol, with no workflow or x-hcx-status codes. For a certificate-only change without passcode validation, /v2/update/cert is the documented shortcut.\\n\\n### Preconditions\\n\\n- The participant already exists and you hold its participant_code.\\n- Bearer token with the Bearer prefix in bearer_auth, plus Accept and Content-Type: application/json.\\n- Body per ParticipantUpdateBody: participant_code and roles are the only required fields; participant_name, scheme_code, linked_registry_codes, address, contact fields, status, signing_cert_path, encryption_cert, endpoint_url and payment_details are optional.\\n- If updating encryption_cert, the new certificate is Base64-encoded and its private key is already deployed on the callback host.\\n- Linked registry codes must validate.\\n\\n### Postconditions\\n\\nHTTP 200 with a string body (the OpenAPI declares string; the sandbox onboarding document shows the participant code echoed back, for example 100001@sbx). The registry record now carries the amended values, and because the gateway reads endpoint_url and encryption_cert from the registry on every leg, callback routing and counterparties\' certificate fetches reflect the change from the next call onwards, subject to their 24-hour certificate cache. No asynchronous callback follows. Failures use the 400/404/500 ErrorResponse envelope.\\n\\n### Common mistakes\\n\\n- Omitting roles on a partial update; it is required even when the change has nothing to do with roles, and its absence yields a 400.\\n- Copying v2 field names (participantcode, encryptioncert, endpointurl) into this snake_case body.\\n- Setting an endpoint_url that uses an IP address or port, or a server outside India, which breaks callback delivery at go-live.\\n- Rotating the certificate in the registry before the new private key is live on the callback host, so inbound callbacks can no longer be decrypted.\\n- Missing the Accept header or the Bearer prefix.\\n\\n### Best practices\\n\\n- Read the current record with /participant/search first and send the full intended state, so a partial body does not unintentionally blank optional fields.\\n- Rotate certificates in two phases and keep the old private key for at least 24 hours, the documented certificate cache TTL.\\n- Confirm callback reachability (domain name, India-based host, NAT IPs 3.109.99.210, 13.126.152.0 and 13.200.129.223 whitelisted) before pointing endpoint_url at a new host.\\n- Log the change with who requested it; registry changes affect where encrypted health data is delivered.\\n\\n### Related scenario\\n\\nA hospital migrates its claims callback service to a new domain. Before touching the registry the team deploys the service, verifies the NHCX NAT IPs are whitelisted and copies the existing PKCS8 private key across. They fetch a Bearer token via /get/session, read the current record with /participant/search, and call /participant/update with participant_code, roles and the new endpoint_url. The registry returns 200. The next /v1/preauth/on_submit callback from the payer arrives at the new domain and is acknowledged with 202 within 30 seconds.\\n\\n### Specification\\n\\nChapter [Your certificate](/docs/nhcx/v1/getting-started/your-certificate) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"participant_code","type":"string","required":false,"description":"","encrypted":false},{"name":"participant_name","type":"string","required":false,"description":"","encrypted":false},{"name":"scheme_code","type":"string","required":false,"description":"","encrypted":false},{"name":"roles","type":"string[]","required":false,"description":"","encrypted":false},{"name":"primaryEmail","type":"string","required":false,"description":"","encrypted":false},{"name":"phone","type":"string[]","required":false,"description":"","encrypted":false},{"name":"primaryMobile","type":"string","required":false,"description":"","encrypted":false},{"name":"endpoint_url","type":"string","required":false,"description":"","encrypted":false},{"name":"signing_cert_path","type":"string","required":false,"description":"","encrypted":false},{"name":"encryption_cert","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"participant_code":"<participant code>","participant_name":"Test Hospital","scheme_code":"PMJAY","roles":["10001"],"primaryEmail":"integration@hospital.example","phone":["01123456789"],"primaryMobile":"9876543210","endpoint_url":"https://nhcx.hospital.example","signing_cert_path":"","encryption_cert":"<encryption cert>"},"responses":[{"status":"200","description":"HTTP 200 with a string body (the OpenAPI declares string; the sandbox onboarding document shows the participant code echoed back, for example 100001@sbx).","example":{"_contentType":"string","_body":"100001@sbx"}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/update \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participant_code\\": \\"<participant code>\\",\\n  \\"participant_name\\": \\"Test Hospital\\",\\n  \\"scheme_code\\": \\"PMJAY\\",\\n  \\"roles\\": [\\n    \\"10001\\"\\n  ],\\n  \\"primaryEmail\\": \\"integration@hospital.example\\",\\n  \\"phone\\": [\\n    \\"01123456789\\"\\n  ],\\n  \\"primaryMobile\\": \\"9876543210\\",\\n  \\"endpoint_url\\": \\"https://nhcx.hospital.example\\",\\n  \\"signing_cert_path\\": \\"\\",\\n  \\"encryption_cert\\": \\"<encryption cert>\\"\\n}\'"}');let c={title:"Participant update (v1)",sidebar_label:"Participant update (v1)",sidebar_class_name:"api-method api-method--post",description:"Updates a participant's registry record; participant_code and roles are mandatory, every other field (certificate, endpoint, contacts, status) is optional.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},p,d={},h=[];function l(e){return(0,r.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}}}]);